        _translate = QtCore.QCoreApplication.translate
        DT_para.setWindowTitle(_translate("DT_para", "决策树：参数设置"))
        self.pushButton.setText(_translate("DT_para", "确定"))
        self.pushButton_2.setText(_translate("DT_para", "取消"))
        self.label.setToolTip(_translate("DT_para", "<html><head/><body><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">这是一个通过限制树的最大深度来防止过拟合的关键参数。实践中最优值需通过实验确定，通常建议从一个较小的深度（如3）开始，逐步增加并通过验证集评估效果来选择</span></p></body></html>"))
        self.label.setText(_translate("DT_para", "max_depth"))
        self.label_2.setToolTip(_translate("DT_para", "<html><head/><body><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">随机种子本身并不提升模型的</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">理论性能</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">上限。它只是将随机性“固定”下来，让你得到一個确定的、可比较的结果。</span></p></body></html>"))
        self.label_2.setText(_translate("DT_para", "random_state"))
        self.label_3.setToolTip(_translate("DT_para", "<html><head/><body><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.894118); background-color:#fcfcfc;\">许多机器学习算法在处理不同量纲的特征时会遇到问题。例如，年龄范围在0-100，而收入可能达到数百万。如果不进行缩放，量级大的特征（如收入）在计算距离（如K近邻算法）或优化目标函数（如梯度下降法）时可能会主导整个模型，导致量级小的特征（如年龄）所包含的信息被淹没</span></p><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.894118); background-color:#fcfcfc;\">。特征缩放通过统一量纲来解决这一问题，主要目的包括：</span></p><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">加速模型训练</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">​：特别是对于依赖梯度下降的算法，特征缩放可以使梯度下降的路径更直接，从而</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">显著提高收敛速度</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">​；</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">提升模型性能</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">​：避免某些特征因量纲过大而被模型过度重视，确保所有特征对模型的贡献相对均衡，从而提升模型的预测准确性以及泛化能力。</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">保证公平性</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:15px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#fcfcfc;\">​：对于使用正则化的模型（如Lasso、Ridge回归），特征缩放能确保正则化项对所有特征的系数进行公平的惩罚</span></p></body></html>"))
        self.label_3.setText(_translate("DT_para", "scale_features"))
        self.comboBox_scale_features.setItemText(0, _translate("DT_para", "False"))
        self.comboBox_scale_features.setItemText(1, _translate("DT_para", "True"))
